package android.net;import java.util.*;public final class Uri {final String value;Uri(String value){this.value=value;}public static Uri parse(String value){return new Uri(value);}public String getScheme(){return java.net.URI.create(value).getScheme();}public String getAuthority(){return java.net.URI.create(value).getAuthority();}public List<String> getPathSegments(){return Arrays.asList(java.net.URI.create(value).getPath().substring(1).split("/"));}public String toString(){return value;}public boolean equals(Object o){return o instanceof Uri&&value.equals(o.toString());}public int hashCode(){return value.hashCode();}public static final class Builder {String scheme,authority;List<String> segments=new ArrayList<>();public Builder scheme(String s){scheme=s;return this;}public Builder authority(String s){authority=s;return this;}public Builder appendPath(String s){segments.add(s);return this;}public Uri build(){return parse(scheme+"://"+authority+"/"+String.join("/",segments));}}}
